using System;
using UnityEngine;

namespace AtomIO.Data
{
    /// <summary>
    /// Mirror of the tier_NNN.json files generated by the Level Designer agent.
    /// Field names match the JSON keys exactly so JsonUtility can read them.
    /// </summary>
    [Serializable]
    public class TierConfig
    {
        public int schema_version;
        public int atomic_number;
        public string symbol;
        public string name;
        public string group;
        public string design_source;
        public TierPlayer player;
        public TierEvolution evolution;
        public TierEnemy enemy;
        public TierSpawn spawn;
        public TierEnergy energy;
        public TierArena arena;
        public TierCoreVisual core_visual;
        public TierTrait trait;

        /// <summary>Seconds between enemy spawns after <paramref name="minutes"/> in the arena.</summary>
        public float EnemyIntervalAt(float minutes) =>
            Mathf.Max(spawn.enemy_min_interval_s, spawn.enemy_base_interval_s / (1f + spawn.time_scale_k * minutes));

        /// <summary>Same inverse-time curve applied to orbs and wild electrons.</summary>
        public float ScaledIntervalAt(float baseInterval, float minutes) =>
            Mathf.Max(0.25f, baseInterval / (1f + spawn.time_scale_k * minutes));

        public float EnemyHpAt(float minutes) => enemy.base_hp + enemy.hp_per_minute * minutes;

        /// <summary>Energy grows exponentially with survival time (GDD 1.3.3).</summary>
        public float OrbValueAt(float minutes) => energy.orb_base_value * Mathf.Pow(energy.growth_per_minute, minutes);

        public static Color ParseHex(string hex, Color fallback)
        {
            return ColorUtility.TryParseHtmlString(hex, out var c) ? c : fallback;
        }
    }

    [Serializable]
    public class TierPlayer
    {
        public int max_hp;
        public int electron_slots;
        public int min_orbiting_electrons;
        public int orbiting_electron_damage;
        public int released_electron_damage;
    }

    [Serializable]
    public class TierEvolution
    {
        public int next_atomic_number;
        public int cost_to_next;
        public float base_fail_chance_pct;
        public float pity_step_pct;
    }

    [Serializable]
    public class TierEnemy
    {
        public float base_hp;
        public float hp_per_minute;
        public int contact_damage;
        public float move_speed;
        public float sight_range;
    }

    [Serializable]
    public class TierSpawn
    {
        public float enemy_base_interval_s;
        public float enemy_min_interval_s;
        public float time_scale_k;
        public int max_alive_enemies;
        public float orb_base_interval_s;
        public float electron_base_interval_s;
    }

    [Serializable]
    public class TierEnergy
    {
        public float orb_base_value;
        public float growth_per_minute;
    }

    [Serializable]
    public class TierArena
    {
        public float radius;
        public string background_hex;
        public string grid_hex;
        public string ambient_particle_asset;
    }

    [Serializable]
    public class TierCoreVisual
    {
        public string primary_hex;
        public string secondary_hex;
        public float glow_intensity;
        public string pattern;
        public string texture_asset;
        public string shader_note;
    }

    [Serializable]
    public class TierTrait
    {
        public string name;
        public string description;
        public float move_speed_mult;
        public float orbit_speed_mult;
        public float electron_damage_mult;
        public float max_hp_mult;
    }
}
